using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using OnlineStore.Data;
using OnlineStore.Models;
namespace OnlineStore.Controllers;
public class AdminCategoriesController(StoreContext db) : Controller { public async Task<IActionResult> Index()=>View(await db.Categories.Include(c=>c.Products).ToListAsync()); public IActionResult Create()=>View(); [HttpPost] public async Task<IActionResult> Create(Category c){if(!ModelState.IsValid)return View(c);db.Categories.Add(c);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult> Edit(int id){var c=await db.Categories.FindAsync(id);return c is null?NotFound():View(c);} [HttpPost] public async Task<IActionResult> Edit(Category c){if(!ModelState.IsValid)return View(c);db.Update(c);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult> Delete(int id){var c=await db.Categories.Include(c=>c.Products).FirstOrDefaultAsync(c=>c.Id==id);return c is null?NotFound():View(c);} [HttpPost,ActionName("Delete")] public async Task<IActionResult> DeleteConfirmed(int id){var c=await db.Categories.Include(c=>c.Products).FirstOrDefaultAsync(c=>c.Id==id);if(c is null)return NotFound();if(c.Products.Any()){TempData["Message"]="Cannot delete a category that has products.";return RedirectToAction(nameof(Index));}db.Categories.Remove(c);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} }
